using AuthService.API.Services;
using Microsoft.AspNetCore.Mvc;
using Microsoft.IdentityModel.Tokens;
using System.Text;
using System.IdentityModel.Tokens.Jwt;
using System.Security.Claims;

namespace AuthService.API.Controllers;

[ApiController]
[Route("auth")]
public class LoginController : ControllerBase
{
    private readonly IConfiguration _config;
    private readonly UserService _userService;

    public LoginController(IConfiguration config, UserService userService)
    {
        _config = config;
        _userService = userService;
    }

    [HttpPost("login")]
    public async Task<IActionResult> Login([FromBody] LoginRequest request)
    {
        // نعتبر أن Username = Email
        var user = await _userService.ValidateUserAsync(request.Username, request.Password);

        if (user is null)
            return Unauthorized("Invalid credentials");

        var key = Encoding.UTF8.GetBytes(_config["Jwt:Key"]);
        var creds = new SigningCredentials(new SymmetricSecurityKey(key), SecurityAlgorithms.HmacSha256);

        var claims = new[]
        {
            new Claim(ClaimTypes.NameIdentifier, user.Id.ToString()),
            new Claim(ClaimTypes.Name, user.FullName),
            new Claim(ClaimTypes.Email, user.Email),

            // 🔹 مهم: نأخذ الدور من قاعدة البيانات، وليس ثابت "Patient"
            new Claim(ClaimTypes.Role, user.Role ?? "Patient")
        };

        var token = new JwtSecurityToken(
            issuer: _config["Jwt:Issuer"],
            audience: _config["Jwt:Audience"],
            claims: claims,
            expires: DateTime.UtcNow.AddHours(2),
            signingCredentials: creds
        );

        var tokenString = new JwtSecurityTokenHandler().WriteToken(token);

        // 🔹 نرجّع أيضاً الدور في الـ JSON (لو حبينا نستخدمه لاحقاً في الـ CMS)
        return Ok(new
        {
            token = tokenString,
            role = user.Role
        });
    }
}

public record LoginRequest(string Username, string Password);

using AuthService.API.Services;
using Microsoft.AspNetCore.Mvc;

namespace AuthService.API.Controllers
{
    [ApiController]
    [Route("auth")]
    public class RegisterController : ControllerBase
    {
        private readonly UserService _users;

        public RegisterController(UserService users)
        {
            _users = users;
        }

        [HttpPost("register")]
        public async Task<IActionResult> Register([FromBody] RegisterRequest req)
        {
            // تحقق بسيط جداً هنا (optional)
            if (string.IsNullOrWhiteSpace(req.FullName) ||
                string.IsNullOrWhiteSpace(req.Email) ||
                string.IsNullOrWhiteSpace(req.Password))
            {
                return BadRequest("Missing fields.");
            }

            var ok = await _users.RegisterUserAsync(req.FullName, req.Email, req.Password);

            if (!ok)
                return Conflict("Email already exists");

            return Ok(new { message = "User registered" });
        }
    }

    public record RegisterRequest(string FullName, string Email, string Password);
}

using Microsoft.EntityFrameworkCore;
using System.Collections.Generic;
using System.Reflection.Emit;

namespace AuthService.API.Data
{
    public class AuthDbContext : DbContext
    {
        public AuthDbContext(DbContextOptions<AuthDbContext> options) : base(options) { }

        public DbSet<UserEntity> Users => Set<UserEntity>();

        protected override void OnModelCreating(ModelBuilder modelBuilder)
        {
            modelBuilder.Entity<UserEntity>()
                .HasIndex(u => u.Email)
                .IsUnique();
        }

    }
}

namespace AuthService.API.Data
{
    public class UserEntity
    {
        public Guid Id { get; set; } = Guid.NewGuid();
        public string FullName { get; set; }
        public string Email { get; set; }   // unique
        public string PasswordHash { get; set; }

        public string Role { get; set; } = "Patient";
    }
}

