using Microsoft.AspNetCore.Mvc;
using Umbraco.Cms.Web.Website.Controllers;
using Umbraco.Cms.Core.Cache;
using Umbraco.Cms.Core.Logging;
using Umbraco.Cms.Core.Services;
using Umbraco.Cms.Core.Web;
using Umbraco.Cms.Infrastructure.Persistence;
using Umbraco.Cms.Core.Routing;
using Microsoft.AspNetCore.Http;

using DentalClinic.Cms.Models;
using DentalClinic.Cms.Services;
using System.Linq;
using System.Threading.Tasks;

namespace DentalClinic.Cms.Controllers
{
    public class BookingController : SurfaceController
    {
        private readonly IAppointmentApiClient _appointmentApi;
        private readonly IAuthApiClient _authApi;
        private readonly IDentistApiClient _dentistApi;
        private readonly IHttpContextAccessor _httpContextAccessor;

        public BookingController(
            IUmbracoContextAccessor umbracoContextAccessor,
            IUmbracoDatabaseFactory databaseFactory,
            ServiceContext services,
            AppCaches appCaches,
            IProfilingLogger logger,
            IPublishedUrlProvider publishedUrlProvider,
            IAppointmentApiClient appointmentApi,
            IAuthApiClient authApi,
            IDentistApiClient dentistApi,
            IHttpContextAccessor httpContextAccessor
        ) : base(umbracoContextAccessor, databaseFactory, services, appCaches, logger, publishedUrlProvider)
        {
            _appointmentApi = appointmentApi;
            _authApi = authApi;
            _dentistApi = dentistApi;
            _httpContextAccessor = httpContextAccessor;
        }

        // -----------------------------------------------------
        // POST — Submitting the booking
        // -----------------------------------------------------
        [HttpPost]
        public async Task<IActionResult> SubmitBooking(BookingFormModel model)
        {
            // 1) Validation على المدخلات
            if (!ModelState.IsValid)
            {
                var errors = ModelState.Values
                    .SelectMany(v => v.Errors)
                    .Select(e => e.ErrorMessage)
                    .ToList();

                TempData["errors"] = string.Join(" | ", errors);
                return CurrentUmbracoPage();
            }

            // 2) التأكد من أن المستخدم مسجّل الدخول
            var token = _httpContextAccessor.HttpContext?.Session.GetString("jwt");

            if (string.IsNullOrEmpty(token))
            {
                TempData["errors"] = "You must be logged in before booking an appointment.";
                return CurrentUmbracoPage();
            }

            _appointmentApi.SetAuthToken(token);

            // 3) استدعاء الـ Gateway لإنشاء الموعد
            var appointmentId = await _appointmentApi.CreateAppointmentAsync(model);

            if (appointmentId == null)
            {
                TempData["errors"] = "Failed to create booking through Gateway.";
                return CurrentUmbracoPage();
            }

            // 4) تحويل المستخدم إلى صفحة الدفع مع المبلغ
            decimal amount = 250m;
            TempData["message"] = "Booking created. Redirecting to payment...";

            return Redirect($"/Payment?bookingId={appointmentId}&amount={amount}");
        }
    }
}

using DentalClinic.Cms.Models;
using DentalClinic.Cms.Services;
using Microsoft.AspNetCore.Mvc;
using Microsoft.AspNetCore.Mvc.ViewEngines;
using Microsoft.Extensions.Logging;
using System.Linq;
using Umbraco.Cms.Core.Web;
using Umbraco.Cms.Web.Common.Controllers;

namespace DentalClinic.Cms.Controllers
{
    public class BookingPageController : RenderController
    {
        private readonly IDentistApiClient _dentistApi;

        public BookingPageController(
            ILogger<RenderController> logger,
            ICompositeViewEngine viewEngine,
            IUmbracoContextAccessor umbracoContextAccessor,
            IDentistApiClient dentistApi
        ) : base(logger, viewEngine, umbracoContextAccessor)
        {
            _dentistApi = dentistApi;
        }

        public override IActionResult Index()
        {
            // Async call — safe sync wrapper
            var apiDentists = _dentistApi
                .GetDentistsAsync()
                .GetAwaiter()
                .GetResult();

            var dentists = apiDentists.Select(d => new DentistViewModel
            {
                Id = d.Id,
                FullName = d.FullName
            }).ToList();

            var vm = new BookingViewModel
            {
                Dentists = dentists
            };

            return CurrentTemplate(vm);
        }
    }
}

using DentalClinic.Cms.Services;
using Microsoft.AspNetCore.Mvc;
using Umbraco.Cms.Web.Website.Controllers;
using Umbraco.Cms.Core.Web;
using Umbraco.Cms.Infrastructure.Persistence;
using Umbraco.Cms.Core.Services;
using Umbraco.Cms.Core.Cache;
using Umbraco.Cms.Core.Logging;
using Umbraco.Cms.Core.Routing;
using Microsoft.AspNetCore.Http;

namespace DentalClinic.Cms.Controllers
{
    public class DentistDashboardController : SurfaceController
    {
        private readonly IAppointmentApiClient _appointments;
        private readonly IHttpContextAccessor _http;

        public DentistDashboardController(
            IUmbracoContextAccessor umbracoContextAccessor,
            IUmbracoDatabaseFactory databaseFactory,
            ServiceContext services,
            AppCaches appCaches,
            IProfilingLogger logger,
            IPublishedUrlProvider publishedUrlProvider,
            IAppointmentApiClient appointments,
            IHttpContextAccessor http
        ) : base(umbracoContextAccessor, databaseFactory, services, appCaches, logger, publishedUrlProvider)
        {
            _appointments = appointments;
            _http = http;
        }

        [HttpPost]
        public async Task<IActionResult> Confirm(Guid appointmentId)
        {
            var http = _http.HttpContext!;
            var token = http.Session.GetString("jwt");
            var role = http.Session.GetString("CurrentUserRole");

            if (token == null)
            {
                TempData["dashboardMessage"] = "You must be logged in.";
                return Redirect("/login");
            }

            if (!string.Equals(role, "Dentist", StringComparison.OrdinalIgnoreCase))
            {
                TempData["dashboardMessage"] = "You are not allowed to perform this action.";
                return Redirect("/Dentist-Dashboard");
            }

            _appointments.SetAuthToken(token);

            var ok = await _appointments.ConfirmAppointmentAsync(appointmentId);

            TempData["dashboardMessage"] = ok
                ? "Appointment confirmed."
                : "Error confirming appointment.";

            return Redirect("/Dentist-Dashboard");
        }

        [HttpPost]
        public async Task<IActionResult> Cancel(Guid appointmentId)
        {
            var http = _http.HttpContext!;
            var token = http.Session.GetString("jwt");
            var role = http.Session.GetString("CurrentUserRole");

            if (token == null)
            {
                TempData["dashboardMessage"] = "You must be logged in.";
                return Redirect("/login");
            }

            if (!string.Equals(role, "Dentist", StringComparison.OrdinalIgnoreCase))
            {
                TempData["dashboardMessage"] = "You are not allowed to perform this action.";
                return Redirect("/Dentist-Dashboard");
            }

            _appointments.SetAuthToken(token);

            var ok = await _appointments.CancelAppointmentAsync(appointmentId);

            TempData["dashboardMessage"] = ok
                ? "Appointment cancelled."
                : "Error cancelling appointment.";

            return Redirect("/Dentist-Dashboard");
        }
    }
}

using DentalClinic.Cms.Models;
using DentalClinic.Cms.Services;
using Microsoft.AspNetCore.Http;
using Microsoft.AspNetCore.Mvc;
using System.Linq;
using Umbraco.Cms.Core.Cache;
using Umbraco.Cms.Core.Logging;
using Umbraco.Cms.Core.Routing;
using Umbraco.Cms.Core.Services;
using Umbraco.Cms.Core.Web;
using Umbraco.Cms.Infrastructure.Persistence;
using Umbraco.Cms.Web.Website.Controllers;

namespace DentalClinic.Cms.Controllers
{
    public class LoginController : SurfaceController
    {
        private readonly IAuthApiClient _authClient;
        private readonly IHttpContextAccessor _http;

        public LoginController(
            IUmbracoContextAccessor umbracoContextAccessor,
            IUmbracoDatabaseFactory databaseFactory,
            ServiceContext services,
            AppCaches appCaches,
            IProfilingLogger logger,
            IPublishedUrlProvider publishedUrlProvider,
            IAuthApiClient authClient,
            IHttpContextAccessor http
        ) : base(umbracoContextAccessor, databaseFactory, services, appCaches, logger, publishedUrlProvider)
        {
            _authClient = authClient;
            _http = http;
        }

        // 🔹 تسجيل الدخول
        [HttpPost]
        // لا نستخدم ValidateAntiForgeryToken في الـ MVP لتجنّب 400
        public async Task<IActionResult> SubmitLogin(LoginFormModel model)
        {
            // 1) التحقق من صحة المدخلات
            if (!ModelState.IsValid)
            {
                var errors = ModelState.Values
                    .SelectMany(v => v.Errors)
                    .Select(e => e.ErrorMessage)
                    .ToList();

                TempData["errors"] = string.Join(" | ", errors);
                return RedirectToCurrentUmbracoPage();
            }

            // 2) استدعاء AuthService عبر IAuthApiClient
            var loginResult = await _authClient.LoginAsync(model.Email, model.Password);

            if (loginResult == null || string.IsNullOrEmpty(loginResult.token))
            {
                TempData["errors"] = "Invalid email or password.";
                return RedirectToCurrentUmbracoPage();
            }

            var http = _http.HttpContext!;

            // 3) حفظ التوكن في Session
            http.Session.SetString("jwt", loginResult.token);
            http.Session.SetString("CurrentUserEmail", model.Email);

            // 4) حفظ الدور في Session (Patient أو Dentist)
            var roleValue = loginResult.role ?? "Patient";
            http.Session.SetString("CurrentUserRole", roleValue);

            TempData["message"] = "You are now logged in.";

            return Redirect("/");
        }

        // 🔹 تسجيل الخروج
        [HttpPost]
        // برضه بدون ValidateAntiForgeryToken في الـ MVP
        public IActionResult Logout()
        {
            var http = _http.HttpContext;

            if (http != null)
            {
                http.Session.Remove("jwt");
                http.Session.Remove("CurrentUserEmail");
                http.Session.Remove("CurrentUserName");
                http.Session.Remove("CurrentUserRole");
                // أو http.Session.Clear();
            }

            TempData["message"] = "You have been logged out.";

            return Redirect("/");
        }
    }
}

