@inherits Umbraco.Cms.Web.Common.Views.UmbracoViewPage<DentalClinic.Cms.Models.BookingViewModel>
@using DentalClinic.Cms.Controllers

@{
    Layout = "master.cshtml";
}

<h1>Book an Appointment</h1>
@await Html.PartialAsync("Partials/_FlashMessages")

@* عرض الأخطاء *@
@* @if (TempData["errors"] != null)
{
    <p style="color:red">@TempData["errors"]</p>
} *@

@* رسائل عامة (نجاح مثلاً) *@
@* @if (TempData["message"] != null)
{
    <p style="color:green">@TempData["message"]</p>
} *@

@using (Html.BeginUmbracoForm<BookingController>("SubmitBooking"))
{
    <label>Full Name</label><br />
    <input type="text" name="FullName" /><br /><br />

    <label>Dentist</label><br />
    <select name="DentistId">
        <option value="">-- Select a Dentist --</option>

        @if (Model?.Dentists != null)
        {
            foreach (var d in Model.Dentists)
            {
                <option value="@d.Id">@d.FullName</option>
            }
        }
    </select>
    <br /><br />

    <label>Date</label><br />
    <input type="date" name="Date" /><br /><br />

    <label>Time</label><br />
    <input type="time" name="Time" /><br /><br />

    <button type="submit">Book Appointment</button>
}

@using DentalClinic.Cms.Models
@using DentalClinic.Cms.Services
@using DentalClinic.Cms.Controllers
@using Microsoft.AspNetCore.Http
@inherits Umbraco.Cms.Web.Common.Views.UmbracoViewPage

@inject IAppointmentApiClient Appointments
@inject IHttpContextAccessor HttpContextAccessor

@{
    Layout = "master.cshtml";

    var http = HttpContextAccessor.HttpContext!;
    var token = http.Session.GetString("jwt");
    var role = http.Session.GetString("CurrentUserRole");

    var pageTitle = Model.Value<string>("pageTitle") ?? "Dentist Admin Panel";
    var introText = Model.Value<string>("introText");

    List<AppointmentResult> appointments = new();

    // ✅ فقط لو المستخدم Dentist نقرأ المواعيد من الـ API
    if (!string.IsNullOrEmpty(token) &&
        string.Equals(role, "Dentist", StringComparison.OrdinalIgnoreCase))
    {
        Appointments.SetAuthToken(token);

        appointments = await Appointments.GetAdminAppointmentsAsync()
                       ?? new List<AppointmentResult>();
    }

    // 🔹 فلترة المواعيد: نعرض فقط Requested + Confirmed وبشكل مرتب
    var activeAppointments = (appointments ?? new List<AppointmentResult>())
        .Where(a => a.Status == "Requested" || a.Status == "Confirmed")
        .OrderBy(a => a.Slot?.Date)
        .ThenBy(a => a.Slot?.Time)
        .ToList();
}

<h1>@pageTitle</h1>
@await Html.PartialAsync("Partials/_FlashMessages")

@* @if (!string.IsNullOrWhiteSpace(introText))
{
    <div>
        @Html.Raw(introText)
    </div>
