using PaymentService.Domain.ValueObjects;
using DentalClinic.SharedKernel.DomainEvents;

namespace PaymentService.Application;

public class PaymentApplicationService
{
    private readonly IPaymentRepository _repository;

    public PaymentApplicationService(IPaymentRepository repository)
    {
        _repository = repository;
    }

    public async Task HandleAppointmentConfirmed(AppointmentConfirmedEvent evt)
    {
        var payment = new Payment(
            Guid.NewGuid(),
            evt.AppointmentId,
            new Money(500, "DKK") // مبلغ افتراضي مؤقت
        );

        await _repository.AddAsync(payment);

        Console.WriteLine($"💰 Payment created for appointment {evt.AppointmentId}");
    }

    public async Task HandleCreate(Guid paymentId, Guid appointmentId, decimal totalAmount)
    {
        var payment = new Payment(paymentId, appointmentId, new Money(totalAmount));
        await _repository.AddAsync(payment);
    }

    public async Task HandleAuthorize(Guid paymentId)
    {
        var payment = await _repository.GetByIdAsync(paymentId)
            ?? throw new InvalidOperationException("Payment not found.");

        payment.Authorize();
        await _repository.UpdateAsync(payment);
    }

    public async Task HandleCapture(Guid paymentId)
    {
        var payment = await _repository.GetByIdAsync(paymentId)
            ?? throw new InvalidOperationException("Payment not found.");

        payment.Capture();
        await _repository.UpdateAsync(payment);
    }

    public async Task HandleRefund(Guid paymentId)
    {
        var payment = await _repository.GetByIdAsync(paymentId)
            ?? throw new InvalidOperationException("Payment not found.");

        payment.Refund();
        await _repository.UpdateAsync(payment);
    }
}

using DentalClinic.SharedKernel;
using PaymentService.Domain.ValueObjects;

namespace PaymentService.Domain.Entities;

public enum PaymentStatus
{
    Pending,
    Authorized,
    Captured,
    Failed,
    Refunded
}

public sealed class Payment : AggregateRoot
{
    public Guid AppointmentId { get; init; }
    public Money Total { get; private set; }
    public PaymentStatus Status { get; private set; } = PaymentStatus.Pending;

    // ✅ Constructor المستخدم في الكود العادي
    public Payment(Guid id, Guid appointmentId, Money total)
        : base(id)
    {
        AppointmentId = appointmentId;
        Total = total;
    }

    // ✅ Constructor فارغ خاص بـ EF Core
    private Payment() : base(Guid.Empty) { }

    public void Authorize()
    {
        if (Status != PaymentStatus.Pending)
            throw new InvalidOperationException("Only pending payments can be authorized.");
        Status = PaymentStatus.Authorized;
    }

    public void Capture()
    {
        if (Status != PaymentStatus.Authorized)
            throw new InvalidOperationException("Only authorized payments can be captured.");
        Status = PaymentStatus.Captured;
    }

    public void Fail() => Status = PaymentStatus.Failed;

    public void Refund()
    {
        if (Status != PaymentStatus.Captured)
            throw new InvalidOperationException("Only captured payments can be refunded.");
        Status = PaymentStatus.Refunded;
    }
}

